package studio.cardia.core

object KidneyContent {
    private const val LEFT = "VH_M_left_kidney"
    private const val LEFT_TRACT = "VH_M_renal_pelvis_ureter_L"
    private val section = Cut(Axis.Coronal, through = LEFT)
    private val kidneyTissue = listOf("capsule", "hilum", "cortex", "columns", "pyramids", "papillae")

    val organ = Organ(
        id = "kidney", name = "Kidneys & urinary tract", system = "Urinary", tagline = "Filter, concentrate, collect, carry.",
        assets = listOf("kidney-l.glb", "kidney-r.glb", "ureter-l.glb", "ureter-r.glb", "urinary-bladder.glb"),
        layers = listOf("Capsule", "Cortex", "Medulla", "Collecting system"),
        note = "Kidneys, collecting systems, ureters and bladder from one reference body, in their true relative positions. Renal vessels, adrenal glands, fat and urethra are not included.",
        structures = listOf(
            Structure("capsule", "Renal capsule", "Fibrous outer covering", "A thin, tough fibrous layer closely applied to the surface of each kidney. Outside it (not modelled) lie perirenal fat and renal fascia.", "Stretching of the capsule, for example when an obstructed kidney swells, contributes to flank pain.", listOf("VH_M_kidney_capsule_L", "VH_M_kidney_capsule_R")),
            Structure("hilum", "Renal hilum", "Doorway on the medial border", "A vertical slit on the concave medial border through which the renal vein, renal artery and renal pelvis pass, together with lymphatics and nerves.", "Typical order from front to back: vein, artery, pelvis. The vessels themselves are not in this model.", listOf("VH_M_hilum_of_kidney_L", "VH_M_hilum_of_kidney_R")),
            Structure("cortex", "Renal cortex", "Filtration zone", "The outer layer of kidney tissue. It contains the renal corpuscles (glomerulus and Bowman's capsule) and the proximal and distal convoluted tubules, where filtrate is formed and first modified.", "Roughly a fifth of the cardiac output flows to the kidneys at rest, and most of it perfuses the cortex.", listOf("VH_M_outer_cortex_of_kidney_L", "VH_M_outer_cortex_of_kidney_R"), depth = 1, tint = 0xE2B8A4),
            Structure("columns", "Renal columns", "Cortex between pyramids", "Extensions of cortical tissue that dip between neighbouring renal pyramids. Interlobar arteries and veins run through them.", "Also called columns of Bertin. A prominent column can mimic a mass on ultrasound.", listOf("VH_M_renal_column_L", "VH_M_renal_column_R"), depth = 1, tint = 0xD9AC98),
            Structure("pyramids", "Renal pyramids", "The medulla", "Cone-shaped regions of medulla with their bases toward the cortex. They contain loops of Henle, vasa recta and collecting ducts, which together concentrate urine.", "This reference body has nine pyramids in the left kidney and ten in the right.", listOf("VH_M_renal_pyramid_L", "VH_M_renal_pyramid_R"), depth = 2, tint = 0x8E4550),
            Structure("papillae", "Renal papillae", "Tips of the pyramids", "The apex of each pyramid, where papillary collecting ducts (of Bellini) open into a minor calyx. Urine is at its most concentrated here.", "Randall's plaques — the seeds of most calcium oxalate stones — form in the papillary interstitium.", listOf("VH_M_renal_papilla_L", "VH_M_renal_papilla_R"), depth = 2, tint = 0x9E3F4C),
            Structure("minor", "Minor calyces", "Cups around the papillae", "Cup-shaped tubes that each receive urine from one or more papillae and join to form the major calyces.", "Urine leaving a papilla is final urine: no further reabsorption happens in the calyces, pelvis or ureter.", listOf("VH_M_minor_calyx_L", "VH_M_minor_calyx_R"), depth = 3, tint = 0xF1DB8E),
            Structure("major", "Major calyces", "Collecting channels", "Two or three larger channels, each formed by several minor calyces, that drain into the renal pelvis.", "This reference body has three major calyces on the left and two on the right — normal variation.", listOf("VH_M_major_calyx_L", "VH_M_major_calyx_R"), depth = 3, tint = 0xE8C66C),
            Structure("pelvis", "Renal pelvis", "Funnel into the ureter", "The funnel-shaped upper end of the ureter, lying partly within the renal sinus and partly outside the hilum. It narrows at the pelvi-ureteric junction.", "The pelvi-ureteric junction is the first of three physiological narrowings where stones commonly lodge.", listOf("VH_M_renal_pelvis_L", "VH_M_renal_pelvis_R"), depth = 3, tint = 0xDEB252),
            Structure("ureter", "Ureters", "Muscular conduits", "Muscular tubes about 25–30 cm long that carry urine from the renal pelvis to the bladder by peristalsis. They descend retroperitoneally on psoas major and cross the iliac vessels at the pelvic brim.", "Narrowings: pelvi-ureteric junction, pelvic brim, and vesico-ureteric junction — the narrowest.", listOf("VH_M_ureter_L", "VH_M_ureter_R"), depth = 3, tint = 0xD6A54E),
            Structure("dome", "Bladder dome", "Superior wall", "The superior, most distensible part of the bladder wall, covered by peritoneum.", "The adult bladder commonly holds 400–600 mL; the urge to void usually begins well before that.", listOf("VH_M_fundus_of_urinary_bladder_dome"), depth = 3, tint = 0xE3C6A6),
            Structure("base", "Bladder base", "Posterior-inferior wall", "The lower posterior part of the bladder, containing the trigone. The ureters enter it obliquely.", "The oblique intramural course of each ureter acts as a flap valve that limits reflux of urine toward the kidney.", listOf("VH_M_fundus_of_urinary_bladder_base1"), depth = 3, tint = 0xD8B593),
            Structure("trigone", "Trigone", "Smooth triangle", "A smooth triangular area of the bladder base between the two ureteric orifices and the internal urethral orifice.", "Unlike the rest of the bladder lining, the trigone stays smooth when the bladder is empty.", listOf("VH_M_trigone_of_urinary_bladder"), depth = 3, tint = 0xC98E78, decal = true),
            Structure("orifices", "Ureteric orifices", "Where the ureters open", "Slit-like openings at the upper corners of the trigone where each ureter enters the bladder, at the end of the vesico-ureteric junction.", "The vesico-ureteric junction is the commonest place for a passing stone to impact.", listOf("VH_M_ureteral_orifice"), depth = 3, tint = 0xA24E3B, decal = true),
            Structure("neck", "Bladder neck", "Outlet", "The lowest part of the bladder, surrounding the internal urethral orifice, where the bladder joins the urethra.", "In males the smooth muscle here forms the internal urethral sphincter.", listOf("VH_M_urinary_bladder_neck_smooth_muscle"), depth = 3, tint = 0xB57A60)
        ),
        lessons = listOf(
            Lesson("inside", "Inside the kidney", "From capsule to collecting system", 6, listOf(
                LessonStep("Two kidneys, one tract", "The kidneys lie behind the peritoneum on the posterior abdominal wall, roughly from T12 to L3. Each ureter runs down to the bladder in the pelvis.", "This is one real body. Rotate it and compare the two sides — anatomy is rarely perfectly symmetrical.", StudyView(listOf("capsule"), frame = emptyList())),
                LessonStep("The hilum", "On the medial border, the hilum lets the renal vein, renal artery and renal pelvis enter and leave. From front to back the usual order is vein, artery, pelvis.", "The vessels are not in this model; notice where the pelvis emerges.", StudyView(listOf("hilum", "pelvis"), frame = listOf(LEFT))),
                LessonStep("Cut it open: the cortex", "A coronal section through the left kidney. The pale outer cortex holds the glomeruli, where blood is filtered. Renal columns of cortex dip between the pyramids.", "The front half of the kidney has been removed. You are looking at the cut face.", StudyView(listOf("cortex", "columns"), frame = listOf(LEFT), peel = 1, cut = section)),
                LessonStep("Pyramids and papillae", "The medulla is arranged as pyramids. Loops of Henle and collecting ducts here concentrate the urine. Each pyramid ends in a papilla that points into the renal sinus.", "Cortex removed: only medulla and collecting system remain.", StudyView(listOf("pyramids", "papillae"), frame = listOf(LEFT), peel = 2)),
                LessonStep("The collecting system", "Urine drips from each papilla into a minor calyx. Minor calyces join into major calyces, which drain into the renal pelvis.", "Papilla → minor calyx → major calyx → pelvis. Trace one route.", StudyView(listOf("minor", "major", "pelvis"), frame = listOf(LEFT, LEFT_TRACT), peel = 3, ghost = listOf("capsule"))),
                LessonStep("Down to the bladder", "The ureters carry urine by peristalsis and enter the bladder base obliquely at the ureteric orifices, at the corners of the trigone.", "The oblique entry works like a flap valve against reflux.", StudyView(listOf("ureter", "orifices", "trigone"), frame = emptyList(), ghost = listOf("dome")))
            )),
            Lesson("stones", "How a kidney stone forms", "A dissection from crystal to colic", 9, listOf(
                LessonStep("Too much in too little water", "Stones form when urine becomes supersaturated: more calcium, oxalate, phosphate, uric acid or cystine is dissolved than the water can hold. Low urine volume, high urinary calcium or oxalate, low citrate and abnormal urine pH all push urine toward crystallising. Citrate and magnesium are natural inhibitors.", "Most stones (around four in five) are calcium-based, mainly calcium oxalate.", StudyView(listOf("capsule"), frame = listOf(LEFT))),
                LessonStep("Open the kidney", "A coronal section exposes the machinery. Filtrate forms in the cortex; as it passes through the medulla, water is reclaimed and the urine concentrates — and concentration is where crystallisation risk rises.", "Front half removed along the coronal plane.", StudyView(listOf("cortex", "pyramids"), frame = listOf(LEFT), cut = section, peel = 1)),
                LessonStep("The papilla: where it starts", "Most calcium oxalate stones grow on Randall's plaque: deposits of calcium phosphate (apatite) that begin in the basement membranes of the thin loops of Henle deep in the papilla. The plaque spreads beneath the lining; once exposed to urine, calcium oxalate layers onto it and a stone grows anchored to the papilla.", "Pyramids are ghosted so you can see each papilla sitting in its minor calyx. The amber marker is on a lower-pole papilla.", StudyView(listOf("papillae", "minor"), frame = listOf("VH_M_renal_pyramid_L_g", "VH_M_renal_pyramid_L_h", "VH_M_renal_pyramid_L_i", "VH_M_minor_calyx_L_i"), peel = 2, ghost = listOf("pyramids"), markers = listOf(Marker("Randall's plaque stone", Anchor("VH_M_renal_papilla_L_i"))))),
                LessonStep("Free in a calyx", "A stone may break off its plaque and lie in a minor calyx. Stones in the lower-pole calyces tend to stay: urine must drain upward, against gravity, to leave them when you stand. Many calyceal stones cause no symptoms for years.", "Kidney tissue is ghosted so you can see the collecting system.", StudyView(listOf("minor"), frame = listOf(LEFT, "VH_M_renal_pelvis_L"), peel = 3, ghost = listOf("capsule"), markers = listOf(Marker("Lower-pole calyceal stone", Anchor("VH_M_minor_calyx_L_i"))))),
                LessonStep("Staghorn stones", "Some stones grow to fill the renal pelvis and branch into the calyces, like antlers. These staghorn calculi are classically struvite (magnesium ammonium phosphate), formed when urease-producing bacteria such as Proteus make urine alkaline. Cystine and uric acid can also form them.", "Markers trace the pelvis and major calyces a staghorn would fill.", StudyView(listOf("pelvis", "major", "minor"), frame = listOf(LEFT), peel = 3, ghost = listOf("capsule"), markers = listOf(Marker("Pelvis", Anchor("VH_M_renal_pelvis_L")), Marker("Upper major calyx", Anchor("VH_M_major_calyx_L_a")), Marker("Middle major calyx", Anchor("VH_M_major_calyx_L_b")), Marker("Lower major calyx", Anchor("VH_M_major_calyx_L_c"))))),
                LessonStep("First narrowing: the PUJ", "When a stone leaves the kidney, the first tight point is the pelvi-ureteric junction, where the wide pelvis becomes the narrow ureter.", "The marker is placed at the top of the ureter mesh, where it meets the pelvis.", StudyView(listOf("pelvis", "ureter"), frame = listOf("VH_M_renal_pelvis_L", LEFT), peel = 3, ghost = kidneyTissue, markers = listOf(Marker("Pelvi-ureteric junction", Anchor("VH_M_ureter_L", AnchorAt.Top))))),
                LessonStep("Down the ureter", "Peristalsis pushes the stone down. The second narrowing is at the pelvic brim, where the ureter crosses the iliac vessels (not modelled). The third and narrowest is the vesico-ureteric junction, where the ureter tunnels through the bladder wall — the commonest place for a stone to stick.", "Marker at the lowest point of the left ureter, next to its orifice in the bladder.", StudyView(listOf("ureter", "orifices"), frame = listOf("VH_M_ureter_L", "VH_M_urinary_bladder"), peel = 3, ghost = listOf("dome", "base"), markers = listOf(Marker("Vesico-ureteric junction", Anchor("VH_M_ureter_L", AnchorAt.Bottom))))),
                LessonStep("Why it hurts", "A stuck stone blocks urine. Pressure rises upstream, and the pelvis and calyces dilate (hydronephrosis). The ureter spasms against the obstruction and the capsule stretches: renal colic — severe, waxing and waning flank pain that can radiate to the groin, often with nausea and blood in the urine.", "The model shows normal anatomy. In obstruction, these highlighted parts would be dilated.", StudyView(listOf("pelvis", "major", "minor", "ureter"), frame = listOf(LEFT, "VH_M_ureter_L"), peel = 3, ghost = listOf("capsule"), markers = listOf(Marker("Obstructing stone", Anchor("VH_M_ureter_L", AnchorAt.Bottom))))),
                LessonStep("Diagnose, treat, prevent", "Low-dose non-contrast CT is the reference test; ultrasound is preferred in pregnancy and children. Most stones of 5 mm or less pass on their own; alpha-blockers can help larger distal ureteric stones pass. Larger stones are treated with shock-wave lithotripsy, ureteroscopy or, for large and staghorn stones, percutaneous nephrolithotomy. An obstructed kidney with fever is an emergency needing urgent drainage. Prevention: drink enough to pass at least about 2.5 L of urine a day, limit salt and animal protein, and keep normal dietary calcium.", "Study summary only — not individual medical advice.", StudyView(listOf("pelvis", "ureter", "orifices"), frame = emptyList()))
            ))
        ),
        questions = listOf(
            Question("Which sequence follows urine correctly?", listOf("Minor calyx → papilla → major calyx → pelvis", "Papilla → minor calyx → major calyx → renal pelvis", "Pelvis → major calyx → minor calyx → ureter", "Cortex → pelvis → papilla → ureter"), 1, "Collecting ducts open at the papilla into a minor calyx; minor calyces join into major calyces, which drain into the pelvis."),
            Question("Renal columns are extensions of which tissue?", listOf("Medulla", "Cortex", "Renal pelvis", "Capsule"), 1, "Renal columns are cortical tissue lying between adjacent pyramids."),
            Question("What is the most common kidney stone composition?", listOf("Uric acid", "Struvite", "Calcium oxalate", "Cystine"), 2, "Calcium stones, mostly calcium oxalate, account for the large majority."),
            Question("Where does Randall's plaque form?", listOf("Glomerulus", "Renal papilla interstitium", "Bladder trigone", "Renal capsule"), 1, "Calcium phosphate deposits begin around the thin loops of Henle in the papilla and act as an anchor for calcium oxalate stones."),
            Question("At which site does a passing ureteric stone most often impact?", listOf("Pelvi-ureteric junction", "Pelvic brim", "Vesico-ureteric junction", "Minor calyx"), 2, "The vesico-ureteric junction, the intramural part of the ureter, is the narrowest point."),
            Question("Staghorn calculi are classically associated with…", listOf("Urease-producing bacteria", "Dehydration alone", "Low urine calcium", "Acidic urine from diet"), 0, "Urease splits urea to ammonia, alkalinising urine and precipitating struvite (magnesium ammonium phosphate)."),
            Question("Which is the reference imaging test for suspected stones in a non-pregnant adult?", listOf("Plain abdominal X-ray", "Low-dose non-contrast CT", "Contrast MRI", "Cystoscopy"), 1, "Non-contrast CT detects nearly all stone types, including uric acid stones that plain X-ray can miss."),
            Question("Which prevention advice is NOT recommended for calcium oxalate stone formers?", listOf("Drink more fluid", "Reduce salt intake", "Severely restrict dietary calcium", "Moderate animal protein"), 2, "Low dietary calcium increases intestinal oxalate absorption and can raise stone risk; normal calcium intake is advised."),
            Question("An obstructing stone with fever needs…", listOf("Fluids and wait", "Urgent drainage of the kidney", "Shock-wave lithotripsy first", "Alpha-blocker only"), 1, "An infected obstructed kidney can cause sepsis; decompression (stent or nephrostomy) is urgent.")
        ),
        references = listOf(
            "NIDDK · Kidney stones" to "https://www.niddk.nih.gov/health-information/urologic-diseases/kidney-stones",
            "OpenStax · Gross anatomy of the kidney" to "https://openstax.org/books/anatomy-and-physiology-2e/pages/25-3-gross-anatomy-of-the-kidney",
            "EAU Guidelines · Urolithiasis" to "https://uroweb.org/guidelines/urolithiasis",
            "Evan et al. 2003 · Randall's plaque origin (J Clin Invest)" to "https://doi.org/10.1172/JCI17038"
        ),
        yaw = 0f, pitch = 0f
    )
}
